// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        bool ok;
        vm.prank(caller);
        try c.transferOwnership(address(1)) {
            ok = true;
        } catch (bytes memory err) {
            ok = false;
            bytes4 panicSelector = bytes4(keccak256("Panic(uint256)"));
            if (err.length >= 4 && bytes4(err) == panicSelector) {
                ok = false;
            } else {
                ok = true;
            }
        }
        assertTrue(ok);
    }
}
